(o/'metrics.html').write_text('''<!doctype html><meta charset="utf-8"><title>Metrics · original isolation</title><button id="metrics-record">Record Metrics</button><iframe width="1000" height="700" src="metrics-inner.html?viewport=1000"></iframe><iframe width="1280" height="700" src="metrics-inner.html?viewport=1280" style="position:absolute;left:-2000px;visibility:hidden"></iframe><script>document.querySelector('#metrics-record').onclick=async()=>{const frames=[...document.querySelectorAll('iframe')];for(const f of frames)await f.contentDocument.fonts.ready;const data={dpr:devicePixelRatio,cases:frames.flatMap(f=>f.contentWindow.cases),rows:frames.flatMap(f=>f.contentWindow.read())};const response=await fetch('/evidence/connection-metrics-'+(new URLSearchParams(location.search).get('os')||'mac')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok)throw Error('Record failed');document.querySelector('#metrics-record').textContent='Metrics recorded';}</script>'''.replace('f.contentWindow.cases','f.contentWindow.getCases()'))
