(o/'metrics-lifecycle.html').write_text('''<!doctype html><meta charset="utf-8"><title>Metrics lifecycle · original isolation</title><link rel="stylesheet" href="metrics-original.css"><button id="metrics-run">Run Metrics lifecycle</button><iframe width="1280" height="800" src="metrics-inner.html?viewport=1280" style="position:absolute;left:-2000px"></iframe><iframe width="1000" height="800" src="metrics-inner.html?viewport=1000" style="position:absolute;left:-4000px"></iframe><script>document.querySelector('#metrics-run').onclick=async()=>{const frames=[...document.querySelectorAll('iframe')],f=frames[0];for(const frame of frames)await frame.contentDocument.fonts.ready;const get=id=>f.contentDocument.querySelector('[data-id="'+id+'"]'),n=get('ko-1280-904-0').cloneNode(true),items=[...n.children],holder=f.contentDocument.body,rows=[];n.style.position='static';n.style.visibility='visible';function state(label){const b=n.getBoundingClientRect();rows.push({label,attached:n.isConnected,sameItems:items.every((x,i)=>x===n.children[i]),focusable:n.tabIndex>=0,values:items.map(x=>x.children[1].textContent),effects:items.map(x=>{const s=getComputedStyle(x.children[1]);return{opacity:n.isConnected?Number(s.opacity):null,y:n.isConnected?new DOMMatrix(s.transform).m42:null}}),root:{x:0,y:0,width:b.width,height:b.height}})}function presentation(id){const src=get(id);n.style.width=src.style.width;items.forEach((x,i)=>{x.children[0].textContent=src.children[i].children[0].textContent;x.children[1].textContent=src.children[i].children[1].textContent})}holder.append(n);state('attached-no-auto');const effects=items.slice(0,3).map(x=>x.children[1].animate('''+animate+'''));effects.forEach(x=>{x.pause();x.currentTime=0});state('normal-start');effects.forEach(x=>x.play());await Promise.all(effects.map(x=>x.finished));state('normal-end');n.remove();state('detached');holder.append(n);state('reattached-no-auto');state('reduced');presentation('en-1280-326-2');frames[1].contentDocument.body.append(n);state('narrow-english-reuse');presentation('ko-1280-904-0');holder.append(n);state('wide-korean-reuse');const response=await fetch('/evidence/connection-metrics-'+(new URLSearchParams(location.search).get('os')||'mac')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,viewport:innerWidth,rows})});if(!response.ok)throw Error('Record failed');document.querySelector('#metrics-run').textContent='Metrics lifecycle recorded';}</script>''')
